        r = subprocess.run(["git","show",f"HEAD:{path}"],capture_output=True,text=True)
        cache[path] = r.stdout.split("\n") if r.returncode == 0 else None
    return cache[path]
def resolve(rec):
    lines = head_lines(rec["file"]); ln = rec.get("line")
