        rec["canonical_line_content"] = None; rec["canonical_window"] = None; return
    rec["canonical_line_content"] = lines[ln-1].rstrip()
    win = [lines[ln-1].rstrip()]
    for l in lines[ln:]:
        if len(win) >= 3: break
        if l.strip(): win.append(l.rstrip())
    rec["canonical_window"] = "\n".join(win)
for f in cf:
    resolve(f)
    for m in f.get("members", []) or []:
        resolve(m)
env = {
  "command": "review", "head_sha": os.environ["HEAD_SHA"], "recheck_requests": [], "verdicts": [],
  "all_mode": False, "pass_number": last["pass_number"] + 1,
  "changed_line_ranges": {}, "reviewed_union": [], "file_line_totals": {},
  "carryforward": cf, "findings": [], "codex": {"status": "off"}, "idiom_floor": "medium",
}
print(json.dumps(env))
EOF
)
SCORED=$(printf '%s' "$FINDINGS_ENVELOPE_JSON" | python3 "$SCORE_PY"); SCORE_EXIT=$?
echo "SCORE_EXIT=$SCORE_EXIT"
printf '%s' "$SCORED" > "$TMPDIR/vc_scored.json"
printf '%s' "$SCORED" | python3 -m json.tool

